package com.findupto.voicepos

import android.content.Context
import android.util.Base64
import java.io.File

private const val DEFAULT_NAME = "The Slice Of Heaven"
private const val DEFAULT_ADDRESS = "Old Utility Store near Police Line Khansar Road Bhakkar Punjab Pakistan"
private const val DEFAULT_PHONE = "0332 1872929, 0310 3685151"

class Store(private val context: Context) {
    private val p = context.getSharedPreferences("voice_pos_v5", Context.MODE_PRIVATE)
    init {
        CurrencySettings.symbol = p.getString("currency_symbol", "Rs") ?: "Rs"
        if (!p.getBoolean("defaults_initialized", false)) p.edit().putString("name", (p.getString("name", "") ?: "").ifBlank { DEFAULT_NAME }).putString("address", (p.getString("address", "") ?: "").ifBlank { DEFAULT_ADDRESS }).putString("phone", (p.getString("phone", "") ?: "").ifBlank { DEFAULT_PHONE }).putBoolean("defaults_initialized", true).apply()
    }
    fun cash()=p.getString("cash","0")!!.toDoubleOrNull()?:0.0
    fun setCash(v:Double)=p.edit().putString("cash",v.toString()).apply()
    fun hasOpeningCash()=p.getBoolean("opening",false)
    fun setOpeningCash(v:Double){setCash(v);p.edit().putBoolean("opening",true).apply()}
    fun profile()=CompanyProfile(p.getString("name",DEFAULT_NAME)!!.ifBlank{DEFAULT_NAME},p.getString("address",DEFAULT_ADDRESS)!!.ifBlank{DEFAULT_ADDRESS},p.getString("phone",DEFAULT_PHONE)!!.ifBlank{DEFAULT_PHONE},p.getString("footer","Thank you for your visit")!!,p.getString("logo_path","")!!,p.getBoolean("sale_logo",true),p.getBoolean("kitchen_logo",true),p.getString("currency_symbol","Rs")!!,p.getString("currency_code","PKR")!!,p.getBoolean("tax_enabled",false),p.getString("tax_rate","0")!!.toDoubleOrNull()?:0.0,p.getString("tax_label","Tax")!!,p.getBoolean("service_enabled",false),p.getString("service_rate","0")!!.toDoubleOrNull()?:0.0,p.getString("service_label","Service Charge")!!).also{CurrencySettings.symbol=it.currencySymbol}
    fun saveProfile(x:CompanyProfile)=p.edit().putString("name",x.name).putString("address",x.address).putString("phone",x.phone).putString("footer",x.footer).putString("logo_path",x.logoPath).putBoolean("sale_logo",x.saleLogoEnabled).putBoolean("kitchen_logo",x.kitchenLogoEnabled).putString("currency_symbol",x.currencySymbol).putString("currency_code",x.currencyCode).putBoolean("tax_enabled",x.taxEnabled).putString("tax_rate",x.taxRate.toString()).putString("tax_label",x.taxLabel).putBoolean("service_enabled",x.serviceChargeEnabled).putString("service_rate",x.serviceChargeRate.toString()).putString("service_label",x.serviceChargeLabel).apply().also{CurrencySettings.symbol=x.currencySymbol}
    fun theme()=runCatching{ReceiptTheme.valueOf(p.getString("theme","MODERN")!!)}.getOrDefault(ReceiptTheme.MODERN)
    fun setTheme(t:ReceiptTheme)=p.edit().putString("theme",t.name).apply()
    fun customerPrinterAddress()=p.getString("customer_printer","")? : ""
    fun kitchenPrinterAddress()=p.getString("kitchen_printer","")? : ""
    fun setCustomerPrinterAddress(v:String)=p.edit().putString("customer_printer",v).apply()
    fun setKitchenPrinterAddress(v:String)=p.edit().putString("kitchen_printer",v).apply()
    fun serviceCharge(subtotal:Double):Double{val x=profile();return if(x.serviceChargeEnabled)subtotal*x.serviceChargeRate/100.0 else 0.0}
    fun tax(subtotal:Double):Double{val x=profile();val base=subtotal+serviceCharge(subtotal);return if(x.taxEnabled)base*x.taxRate/100.0 else 0.0}
    fun totalWithTax(subtotal:Double)=subtotal+serviceCharge(subtotal)+tax(subtotal)
    private fun enc(s:String)=s.replace("~","%7E");private fun dec(s:String)=s.replace("%7E","~")
    private fun encodeItems(items:List<SaleItem>)=items.joinToString("|"){"${it.name.replace("~"," ").replace("|"," ")}^${it.qty}^${it.price}"}
    private fun decodeItems(raw:String)=raw.split("|").filter{it.isNotBlank()}.mapNotNull{runCatching{val b=it.split("^");SaleItem(b[0],b[1].toInt(),b[2].toDouble())}.getOrNull()}
    fun sales()=p.getString("sales","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");Sale(a[0].toLong(),decodeItems(a[1]),a[2].toDouble(),a[3].toLong(),dec(a.getOrNull(4).orEmpty()),dec(a.getOrNull(5).orEmpty()),a.getOrNull(6)? : "DINE_IN",dec(a.getOrNull(7).orEmpty()),a.getOrNull(8)? : "CASH",a.getOrNull(9)?.toDoubleOrNull()?:a[2].toDouble(),a.getOrNull(10)?.toDoubleOrNull()?:0.0,a.getOrNull(11)?.toLongOrNull()?:0L,a.getOrNull(12)?.toDoubleOrNull()?:0.0,a.getOrNull(13)?.toDoubleOrNull()?:0.0)}.getOrNull()}
    private fun saveSales(all:List<Sale>)=p.edit().putString("sales",all.joinToString("\n"){"${it.id}~${encodeItems(it.items)}~${it.total}~${it.time}~${enc(it.customerName)}~${enc(it.customerPhone)}~${it.orderType}~${enc(it.customerAddress)}~${it.paymentMethod}~${it.paidAmount}~${it.dueAmount}~${it.shiftId}~${it.serviceCharge}~${it.tax}"}).apply()
    fun addSale(s:Sale){saveSales(sales()+s);if(s.paidAmount>0)addPayment(PaymentRecord(System.currentTimeMillis(),s.id,s.paidAmount,s.paymentMethod,System.currentTimeMillis(),s.shiftId));if(s.dueAmount>0)addDue(DueAccount(s.id,s.id,s.customerName,s.customerPhone,s.total,s.paidAmount,s.time))}
    fun updateSale(s:Sale)=saveSales(sales().map{if(it.id==s.id)s else it})
    fun pending()=p.getString("pending","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");PendingSale(a[0].toLong(),decodeItems(a[1]),a[2].toLong(),dec(a.getOrNull(3).orEmpty()),dec(a.getOrNull(4).orEmpty()),a.getOrNull(5)? : "DINE_IN",dec(a.getOrNull(6).orEmpty()))}.getOrNull()}
    private fun savePending(all:List<PendingSale>)=p.edit().putString("pending",all.joinToString("\n"){"${it.id}~${encodeItems(it.items)}~${it.time}~${enc(it.customerName)}~${enc(it.customerPhone)}~${it.orderType}~${enc(it.customerAddress)}"}).apply()
    fun addPending(s:PendingSale)=savePending(pending()+s);fun replacePending(s:PendingSale)=savePending(pending().map{if(it.id==s.id)s else it});fun removePending(id:Long)=savePending(pending().filterNot{it.id==id})
    fun menu()=p.getString("menu","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("^");MenuItem(a[0].toLong(),a[1],a[2].toDouble(),a.getOrNull(3)?:"",a.getOrNull(4)?:"")}.getOrNull()}
    fun saveMenu(items:List<MenuItem>)=p.edit().putString("menu",items.joinToString("\n"){"${it.id}^${it.name.replace("^"," ")}^${it.price}^${it.variant.replace("^"," ")}^${it.size.replace("^"," ")}"}).apply()
    fun addMenuItem(i:MenuItem)=saveMenu(menu()+i);fun updateMenuItem(i:MenuItem)=saveMenu(menu().map{if(it.id==i.id)i else it});fun removeMenuItem(id:Long)=saveMenu(menu().filterNot{it.id==id})
    fun expenses()=p.getString("expenses","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");Expense(a[0].toLong(),a[1],a[2],a[3].toDouble(),a[4].toLong(),a.getOrNull(5)?:"CASH",a.getOrNull(6)?.toLongOrNull()?:0L)}.getOrNull()}
    fun addExpense(e:Expense)=p.edit().putString("expenses",(expenses()+e).joinToString("\n"){"${it.id}~${it.title.replace("~"," ")}~${it.category.replace("~"," ")}~${it.amount}~${it.time}~${it.paymentMethod}~${it.shiftId}"}).apply()
    fun updateExpense(e:Expense)=p.edit().putString("expenses",expenses().map{if(it.id==e.id)e else it}.joinToString("\n"){"${it.id}~${it.title.replace("~"," ")}~${it.category.replace("~"," ")}~${it.amount}~${it.time}~${it.paymentMethod}~${it.shiftId}"}).apply()
    fun removeExpense(id:Long)=p.edit().putString("expenses",expenses().filterNot{it.id==id}.joinToString("\n"){"${it.id}~${it.title.replace("~"," ")}~${it.category.replace("~"," ")}~${it.amount}~${it.time}~${it.paymentMethod}~${it.shiftId}"}).apply()
    fun shifts()=p.getString("shifts","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");Shift(a[0].toLong(),dec(a[1]),a[2].toLong(),a[3].toDouble(),a.getOrNull(4)?.toLongOrNull()?:0L,a.getOrNull(5)?.toDoubleOrNull()?:0.0,a.getOrNull(6)?:"OPEN")}.getOrNull()}
    private fun saveShifts(all:List<Shift>)=p.edit().putString("shifts",all.joinToString("\n"){"${it.id}~${enc(it.person)}~${it.openedAt}~${it.openingCash}~${it.closedAt}~${it.closingCash}~${it.status}"}).apply()
    fun activeShift()=shifts().lastOrNull{it.status=="OPEN"}
    fun openShift(person:String,openingCash:Double):Shift{activeShift()?.let{closeShift(it.id,openingCash)};val s=Shift(System.currentTimeMillis(),person,System.currentTimeMillis(),openingCash);saveShifts(shifts()+s);return s}
    fun closeShift(id:Long,closingCash:Double){saveShifts(shifts().map{if(it.id==id)it.copy(closedAt=System.currentTimeMillis(),closingCash=closingCash,status="CLOSED")else it})}
    fun shiftSales(id:Long)=sales().filter{it.shiftId==id};fun shiftExpenses(id:Long)=expenses().filter{it.shiftId==id}
    fun payments()=p.getString("payments","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");PaymentRecord(a[0].toLong(),a[1].toLong(),a[2].toDouble(),a[3],a[4].toLong(),a[5].toLong(),dec(a.getOrNull(6).orEmpty()))}.getOrNull()}
    private fun addPayment(x:PaymentRecord)=p.edit().putString("payments",(payments()+x).joinToString("\n"){"${it.id}~${it.saleId}~${it.amount}~${it.method}~${it.time}~${it.shiftId}~${enc(it.note)}"}).apply()
    fun expectedShiftCash(id:Long):Double{val s=shifts().firstOrNull{it.id==id}?:return 0.0;return s.openingCash+payments().filter{it.shiftId==id&&it.method=="CASH"}.sumOf{it.amount}-shiftExpenses(id).filter{it.paymentMethod=="CASH"}.sumOf{it.amount}}
    fun dues()=p.getString("dues","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");DueAccount(a[0].toLong(),a[1].toLong(),dec(a[2]),dec(a[3]),a[4].toDouble(),a[5].toDouble(),a[6].toLong())}.getOrNull()}.filter{it.balance>0.005}
    private fun saveDues(all:List<DueAccount>)=p.edit().putString("dues",all.joinToString("\n"){"${it.id}~${it.saleId}~${enc(it.customerName)}~${enc(it.customerPhone)}~${it.total}~${it.paid}~${it.createdAt}"}).apply()
    private fun addDue(x:DueAccount)=saveDues(dues()+x)
    fun recordPayment(dueId:Long,amount:Double,method:String,shiftId:Long):Boolean{val d=dues().firstOrNull{it.id==dueId}?:return false;val pay=amount.coerceIn(0.0,d.balance);if(pay<=0)return false;addPayment(PaymentRecord(System.currentTimeMillis(),d.saleId,pay,method,System.currentTimeMillis(),shiftId,"Due payment"));val nd=d.copy(paid=d.paid+pay);saveDues(dues().map{if(it.id==d.id)nd else it});sales().firstOrNull{it.id==d.saleId}?.let{updateSale(it.copy(paidAmount=it.paidAmount+pay,dueAmount=(it.total-(it.paidAmount+pay)).coerceAtLeast(0.0)))};return true}
    fun paymentTotals(start:Long=0L,end:Long=Long.MAX_VALUE)=payments().filter{it.time in start..end}.groupBy{it.method}.mapValues{it.value.sumOf(PaymentRecord::amount)}
    fun productTotals(start:Long=0L,end:Long=Long.MAX_VALUE)=sales().filter{it.time in start..end}.flatMap{it.items}.groupBy{it.name}.mapValues{it.value.sumOf(SaleItem::qty)}.toList().sortedByDescending{it.second}
    fun grossSales(start:Long=0L,end:Long=Long.MAX_VALUE)=sales().filter{it.time in start..end}.sumOf{it.total}
    fun realizedSales(start:Long=0L,end:Long=Long.MAX_VALUE)=sales().filter{it.time in start..end}.sumOf{it.paidAmount}
    fun dueTotal()=dues().sumOf{it.balance}
    fun totalExpenses(start:Long=0L,end:Long=Long.MAX_VALUE)=expenses().filter{it.time in start..end}.sumOf{it.amount}
    private fun itemsJson(items:List<SaleItem>)=org.json.JSONArray().apply{items.forEach{put(org.json.JSONObject().apply{put("name",it.name);put("qty",it.qty);put("price",it.price)})}}
    private fun saleJson(s:Sale)=org.json.JSONObject().apply{put("id",s.id);put("time",s.time);put("total",s.total);put("customerName",s.customerName);put("customerPhone",s.customerPhone);put("orderType",s.orderType);put("customerAddress",s.customerAddress);put("paymentMethod",s.paymentMethod);put("paidAmount",s.paidAmount);put("dueAmount",s.dueAmount);put("shiftId",s.shiftId);put("serviceCharge",s.serviceCharge);put("tax",s.tax);put("items",itemsJson(s.items))}
    private fun pendingJson(s:PendingSale)=org.json.JSONObject().apply{put("id",s.id);put("time",s.time);put("customerName",s.customerName);put("customerPhone",s.customerPhone);put("orderType",s.orderType);put("customerAddress",s.customerAddress);put("items",itemsJson(s.items))}
    fun exportBackup():String{val prof=profile();val root=org.json.JSONObject();root.put("format","VOICE_POS_BACKUP_V5");root.put("cash",cash());root.put("opening",hasOpeningCash());root.put("theme",theme().name);root.put("profile",org.json.JSONObject().apply{put("name",prof.name);put("address",prof.address);put("phone",prof.phone);put("footer",prof.footer);put("saleLogo",prof.saleLogoEnabled);put("kitchenLogo",prof.kitchenLogoEnabled);put("logo",prof.logoPath.takeIf{it.isNotBlank()}?.let{runCatching{Base64.encodeToString(File(it).readBytes(),Base64.NO_WRAP)}.getOrDefault("")}?:"");put("currencySymbol",prof.currencySymbol);put("currencyCode",prof.currencyCode);put("taxEnabled",prof.taxEnabled);put("taxRate",prof.taxRate);put("taxLabel",prof.taxLabel);put("serviceEnabled",prof.serviceChargeEnabled);put("serviceRate",prof.serviceChargeRate);put("serviceLabel",prof.serviceChargeLabel)});root.put("menu",org.json.JSONArray().apply{menu().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("name",it.name);put("price",it.price);put("variant",it.variant);put("size",it.size)})}});root.put("sales",org.json.JSONArray().apply{sales().forEach{put(saleJson(it))}});root.put("pending",org.json.JSONArray().apply{pending().forEach{put(pendingJson(it))}});root.put("expenses",org.json.JSONArray().apply{expenses().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("title",it.title);put("category",it.category);put("amount",it.amount);put("time",it.time);put("paymentMethod",it.paymentMethod);put("shiftId",it.shiftId)})}});root.put("shifts",org.json.JSONArray().apply{shifts().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("person",it.person);put("openedAt",it.openedAt);put("openingCash",it.openingCash);put("closedAt",it.closedAt);put("closingCash",it.closingCash);put("status",it.status)})}});root.put("dues",org.json.JSONArray().apply{dues().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("saleId",it.saleId);put("customerName",it.customerName);put("customerPhone",it.customerPhone);put("total",it.total);put("paid",it.paid);put("createdAt",it.createdAt)})}});root.put("payments",org.json.JSONArray().apply{payments().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("saleId",it.saleId);put("amount",it.amount);put("method",it.method);put("time",it.time);put("shiftId",it.shiftId);put("note",it.note)})}});return root.toString()}
    private fun jsonItems(a:org.json.JSONArray)=(0 until a.length()).map{val x=a.getJSONObject(it);SaleItem(x.getString("name"),x.getInt("qty"),x.getDouble("price"))}
    fun importBackup(raw:String){val root=org.json.JSONObject(raw);require(root.optString("format").startsWith("VOICE_POS_BACKUP_V"));val pr=root.getJSONObject("profile");var logoPath=profile().logoPath;val b64=pr.optString("logo","");if(b64.isNotBlank())runCatching{val f=File(context.filesDir,"branding/company_logo.png");f.parentFile?.mkdirs();f.writeBytes(Base64.decode(b64,Base64.DEFAULT));logoPath=f.absolutePath};saveProfile(CompanyProfile(pr.optString("name",DEFAULT_NAME),pr.optString("address",DEFAULT_ADDRESS),pr.optString("phone",DEFAULT_PHONE),pr.optString("footer","Thank you for your visit"),logoPath,pr.optBoolean("saleLogo",true),pr.optBoolean("kitchenLogo",true),pr.optString("currencySymbol","Rs"),pr.optString("currencyCode","PKR"),pr.optBoolean("taxEnabled",false),pr.optDouble("taxRate",0.0),pr.optString("taxLabel","Tax"),pr.optBoolean("serviceEnabled",false),pr.optDouble("serviceRate",0.0),pr.optString("serviceLabel","Service Charge")));setCash(root.optDouble("cash",0.0));p.edit().putBoolean("opening",root.optBoolean("opening",true)).putString("theme",root.optString("theme","MODERN")).apply();val ms=root.optJSONArray("menu")?:org.json.JSONArray();saveMenu((0 until ms.length()).map{val x=ms.getJSONObject(it);MenuItem(x.getLong("id"),x.getString("name"),x.getDouble("price"),x.optString("variant"),x.optString("size"))});val ss=root.optJSONArray("sales")?:org.json.JSONArray();p.edit().putString("sales",(0 until ss.length()).joinToString("\n"){val x=ss.getJSONObject(it);"${x.getLong("id")}~${encodeItems(jsonItems(x.getJSONArray("items")))}~${x.getDouble("total")}~${x.getLong("time")}~${enc(x.optString("customerName"))}~${enc(x.optString("customerPhone"))}~${x.optString("orderType","DINE_IN")}~${enc(x.optString("customerAddress"))}~${x.optString("paymentMethod","CASH")}~${x.optDouble("paidAmount",x.getDouble("total"))}~${x.optDouble("dueAmount",0.0)}~${x.optLong("shiftId",0L)}~${x.optDouble("serviceCharge",0.0)}~${x.optDouble("tax",0.0)}"}).apply();val ps=root.optJSONArray("pending")?:org.json.JSONArray();p.edit().putString("pending",(0 until ps.length()).joinToString("\n"){val x=ps.getJSONObject(it);"${x.getLong("id")}~${encodeItems(jsonItems(x.getJSONArray("items")))}~${x.getLong("time")}~${enc(x.optString("customerName"))}~${enc(x.optString("customerPhone"))}~${x.optString("orderType","DINE_IN")}~${enc(x.optString("customerAddress"))}"}).apply();val es=root.optJSONArray("expenses")?:org.json.JSONArray();p.edit().putString("expenses",(0 until es.length()).joinToString("\n"){val x=es.getJSONObject(it);"${x.getLong("id")}~${x.getString("title")}~${x.getString("category")}~${x.getDouble("amount")}~${x.getLong("time")}~${x.optString("paymentMethod","CASH")}~${x.optLong("shiftId",0L)}"}).apply();val ds=root.optJSONArray("dues")?:org.json.JSONArray();p.edit().putString("dues",(0 until ds.length()).joinToString("\n"){val x=ds.getJSONObject(it);"${x.getLong("id")}~${x.getLong("saleId")}~${enc(x.optString("customerName"))}~${enc(x.optString("customerPhone"))}~${x.getDouble("total")}~${x.getDouble("paid")}~${x.getLong("createdAt")}"}).apply();val sh=root.optJSONArray("shifts")?:org.json.JSONArray();p.edit().putString("shifts",(0 until sh.length()).joinToString("\n"){val x=sh.getJSONObject(it);"${x.getLong("id")}~${enc(x.optString("person"))}~${x.getLong("openedAt")}~${x.getDouble("openingCash")}~${x.optLong("closedAt",0L)}~${x.optDouble("closingCash",0.0)}~${x.optString("status","OPEN")}"}).apply();val pay=root.optJSONArray("payments")?:org.json.JSONArray();p.edit().putString("payments",(0 until pay.length()).joinToString("\n"){val x=pay.getJSONObject(it);"${x.getLong("id")}~${x.getLong("saleId")}~${x.getDouble("amount")}~${x.getString("method")}~${x.getLong("time")}~${x.getLong("shiftId")}~${enc(x.optString("note"))}"}).apply()}
}
